window.AUTH=window.AUTH||{};window.AUTH["17-586"]={"d":"17-586","id":"2017/17-586","n":"Abbott v. Perez","briefs":[{"k":"reply","label":"Reply of appellants Greg Abbott, Governor of Texas, et al.","date":"2017-12-04","url":"https://www.supremecourt.gov/DocketPDF/17/17-586/22390/20171204131210659_17-586_Reply.pdf","side":"pet","n":0},{"k":"petitioner","label":"Brief of appellants Greg Abbott, Governor of Texas, et al.","date":"2018-02-26","url":"https://www.supremecourt.gov/DocketPDF/17/17-586/36656/20180226154657309_17-586%2017-626%20Brief.pdf","side":"pet","n":52},{"k":"respondent","label":"Brief of appellee United States in support of appellants","date":"2018-02-26","url":"https://www.supremecourt.gov/DocketPDF/17/17-586/36714/20180226194103481_17-586%2017-626%20tsUnitedStates.pdf","side":"res","n":62},{"k":"respondent","label":"Brief of appellees Perez, et al. (Congressional Districts)","date":"2018-03-28","url":"https://www.supremecourt.gov/DocketPDF/17/17-586/40389/20180328144214001_17-586BriefForAppellees.pdf","side":"res","n":39},{"k":"respondent","label":"Brief of appellees Perez, et al. (State House Districts)","date":"2018-03-28","url":"https://www.supremecourt.gov/DocketPDF/17/17-586/40362/20180328132926854_17-626bs.pdf","side":"res","n":50},{"k":"reply","label":"Reply of appellants Greg Abbott, Governor of Texas, et al.","date":"2018-04-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-586/43731/20180417155550578_17-586%2017-626%20rb.pdf","side":"pet","n":32}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Abbott v. Perez","cite":"138 S. Ct. 49","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./138/49/","sc":1,"by":{"1":"14"}},{"t":"case","label":"Abrams v. Johnson","cite":"521 U.S. 74","y":1997,"id":"1996/95-1425","sc":1,"sum":"First, the Court held that in re-drafting the plans, the District Court had no obligation to preserve all three of the old plan's black-majority districts, if this would result in racial gerrymandering. Second, the Court supported the District Court's decision not to preserve two black-majority districts as it held that the area's black population was not sufficiently compact to sustain such a plan.","sumSrc":"Oyez","by":{"1":"6","2":"6"}},{"t":"case","label":"Ala. Legis. Black Caucus v. Alabama","cite":"135 S. Ct. 1257","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1257/","sc":1,"by":{"1":"45, 69","3":"passim","4":"52"}},{"t":"case","label":"Am. Library Ass’n v. Barr","cite":"956 F.2d 1178","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/956/1178/","by":{"1":"36"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Bartlett v. Strickland","cite":"556 U.S. 1","y":2009,"id":"2008/07-689","sc":1,"ar":1,"sum":"The Court found that the Voting Rights Act of 1965 did not require redistricting in a county lacking a numerical majority of a racial minority of citizens.","sumSrc":"Oyez","by":{"1":"39, 40, 49, 65","2":"5, 10","3":"25, 40-41","4":"48, 49","5":"3, 16, 21, 22, 31"}},{"t":"case","label":"Bethune-Hill v. Va. State Bd. of Elections","cite":"137 S. Ct. 788","y":2017,"id":"2016/15-680","sc":1,"ar":1,"sum":"The Court determined that race can be shown to be the predominant factor in redistricting even when traditional principles are respected, and that district courts must engage in a holistic analysis.","sumSrc":"Oyez","by":{"1":"45, 48, 49, 69","2":"6, 27, 45, 47","3":"42","5":"25, 29"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Brown v. Thomson","cite":"462 U.S. 835","y":1983,"id":"1982/82-65","sc":1,"sum":"The Court upheld the Wyoming apportionment scheme and found no Fourteenth Amendment violations.","sumSrc":"Oyez","by":{"1":"56"}},{"t":"case","label":"Burke v. Barnes","cite":"479 U.S. 361","y":1987,"id":"1986/85-781","sc":1,"sum":"The case is moot. Article III requires that there be a live case or controversy at the time a federal court decides the case; it is not enough that there may have been a live case or controversy when the case was decided by the court whose judgment this Court is reviewing. Here, any issues as to whether the bill in question became law were mooted when it expired by its own terms, regardless of whether it had been …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Bush v. Vera","cite":"517 U.S. 952","y":1996,"id":"1995/94-805","sc":1,"sum":"In a 5-to-4 decision, the Court held that the Texas redistricting plans were unconstitutional. Supporting its \"strict scrutiny\" approach, the Court noted that the proposed districts were highly irregular in shape, that their computerized design was significantly more sensitive to racial data, and that they lacked any semblance to pre-existing race-neutral districts.","sumSrc":"Oyez","by":{"1":"34, 72","2":"6","3":"36-37","5":"32"}},{"t":"case","label":"Calderon v. U.S. Dist. Ct. for Cent. Dist. of Cal.","cite":"137 F.3d 1420","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/137/1420/","by":{"1":"22"}},{"t":"case","label":"Carson v. Am. Brands, Inc.","cite":"450 U.S. 79","y":1981,"id":"1980/79-1236","sc":1,"ar":4,"sum":"The District Court's interlocutory order refusing to enter the consent decree was an order \"refusing\" an \"injunction\" and was therefore appealable under § 1292 (a) (1).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 19, 22, 23","2":"17, 20","3":"26","4":"30, 33","5":"5, 6"}},{"t":"case","label":"Chapman v. Meier","cite":"420 U.S. 1","y":1975,"id":"1974/73-1406","sc":1,"sum":"This case involves the issue of the constitutionality of a federalcourt-ordered reapportionment of the North Dakota Legislative Assembly. Following protracted state and federal litigation challenging various apportionment plans, statutes, and state constitutional provisions, including a federal action in which a three-judge District Court in 1965 approved a reapportionment plan that included five multimember …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 25, 31"}},{"t":"case","label":"City of Mesquite v. Aladdin’s Castle, Inc.","cite":"455 U.S. 283","y":1982,"id":"1981/80-1577","sc":1,"sum":"Section 6 of appellant Texas city's licensing ordinance governing coin-operated amusement establishments directs the Chief of Police to consider whether a license applicant has any \"connections with criminal elements.\" After receiving recommendations from the Chief of Police, the Chief Building Inspector, and the City Planner, the City Manager decides whether to grant a license. If he denies the license, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43","3":"31"}},{"t":"case","label":"Cohen v. Bd. of Trs. of the Univ. of Med. & Dentistry of N.J.","cite":"867 F.2d 1455","y":1989,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/867/1455/","by":{"1":"22"}},{"t":"case","label":"Connor v. Waller","cite":"421 U.S. 656","y":1975,"id":"1974/74-1509","sc":1,"sum":"The District Court's error in holding that certain Mississippi statutes do not have to be submitted for clearance pursuant to § 5 of the Voting Rights Act of 1965, and its consequent error in deciding the constitutional challenges to the statutes based on racial discrimination claims, require reversal; but this is without prejudice to that court's authority to entertain an appropriate proceeding to require that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Cooper v. Harris","cite":"137 S. Ct. 1455","y":2017,"id":"2016/15-1262","sc":1,"sum":"The Court determined that the district court did not error in determining that North Carolina’s new districting plan constituted an unconstitutional racial gerrymander, and neither claim nor issue preclusion based on the state court case dictate the outcome of this case.","sumSrc":"Oyez","by":{"1":"passim","2":"passim","3":"passim","4":"31, 41, 42, 53","5":"5, 29, 30, 33"}},{"t":"case","label":"Cotton v. Fordice","cite":"157 F.3d 388","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/157/388/","sum":"Finding new version of law comparable to law invalidated in Hunter constitutional because, inter alia, legislature did not enact it for a discriminatory purpose.","sumSrc":"brief:1","by":{"1":"33","2":"34"}},{"t":"case","label":"Davis v. Abbott","cite":"781 F.3d 207","y":2015,"url":"https://www.courtlistener.com/c/F.3d/781/207/","by":{"1":"42","2":"7"}},{"t":"case","label":"Diffenderfer v. Cent. Baptist Church of Miami","cite":"404 U.S. 412","y":1972,"id":"1971/70-47","sc":1,"sum":"The subsequent repeal of the challenged statute and enact-' ment of new legislation make the relief sought inappropriate. The District Court's judgment upholding the statute is vacated and the case is remanded with leave to appellants to amend their pleadings if they desire to attack the new statute or show that the old statute retains some force. 316 F. Supp. 1116, vacated and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Etuk v. Slattery","cite":"936 F.2d 1433","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/936/1433/","by":{"1":"19"}},{"t":"case","label":"Evenwel v. Abbott","cite":"136 S. Ct. 1120","y":2016,"id":"2015/14-940","sc":1,"sum":"The Court determined that the “one person, one vote” principle of the Equal Protection Clause allows a state to draw its legislative districts based on total population.","sumSrc":"Oyez","by":{"1":"57"}},{"t":"case","label":"Growe v. Emison","cite":"507 U.S. 25","y":1993,"id":"1992/91-1420","sc":1,"sum":"Shortly after a group of Minnesota voters filed a state-court action against the Minnesota Secretary of State and other election officials, appellee voters filed a similar action against essentially the same officials in the Federal District Court. Both suits alleged that, in light of the 1990 census results, the State's congressional and legislative districts were malapportioned, in violation of the Federal and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31, 42","2":"3","5":"29"}},{"t":"case","label":"Gunn v. Univ. Comm. to End the War in Viet Nam","cite":"399 U.S. 383","y":1970,"id":"1969/7","sc":1,"ar":10,"sum":"The Court held that the Three-Judge Court Act does not allow direct appeals to the Supreme Court of the United States when the a district court does not specifically grant or deny an injunction.","sumSrc":"Oyez","by":{"1":"22","2":"23","3":"27","4":"29, 30, 31, 32","5":"6, 7"}},{"t":"case","label":"Harris v. Ariz. Indep. Redistricting Comm’n","cite":"136 S. Ct. 1301","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1301/","sc":1,"by":{"1":"57, 58, 62"}},{"t":"case","label":"Hunt v. Cromartie","cite":"526 U.S. 541","y":1999,"id":"1998/98-85","sc":1,"sum":"The Court held that despite strong evidence of racial gerrymandering, the North Carolina General Assembly's motivations were in dispute. As such, further inquiry was warranted on this alone. Moreover, since accusations of racial gerrymandering rise to the level of being constitutionally significant, they must be evaluated with strict scrutiny.","sumSrc":"Oyez","by":{"1":"45, 55","2":"5, 17, 25, 26, 27, 37","4":"41","5":"18, 25"}},{"t":"case","label":"Hunter v. Underwood","cite":"471 U.S. 222","y":1985,"id":"1984/84-76","sc":1,"sum":"Section 182 violates the Equal Protection Clause of the Fourteenth Amendment. Arlington Heights v. MetropolitanHousingDevelopment Corp., 429 U. S. 252. That § 182 may have been adopted to discriminate against poor whites as well as against blacks would not render nugatory the purpose to discriminate against blacks, it being clear that the latter was a \"but-for\" motivation for adopting § 182. There is no evidence …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32","2":"33","3":"30, 31","4":"44, 45","5":"9, 10"}},{"t":"case","label":"Johnson v. De Grandy","cite":"512 U.S. 997","y":1994,"id":"1993/92-519","sc":1,"sum":"In these consolidated cases, a group of Hispanic voters, a group of black voters, and the Federal Government claim that Florida's reapportionment plan for the State's single-member Senate and House districts (SJR 2-G) unlawfully dilutes the voting strength of Hispanics and blacks in the Dade County area, in violation of §2 of the Voting Rights Act of 1965. The State Supreme Court, in a review required by the State …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49, 59, 65","2":"5, 38","3":"4","4":"47"}},{"t":"case","label":"Knox v. SEIU, Local 1000","cite":"567 U.S. 298","y":2012,"id":"2011/10-1121","sc":1,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Lewis v. Cont’l Bank Corp.","cite":"494 U.S. 472","y":1990,"id":"1989/87-1955","sc":1,"sum":"Before 1987, the Bank Holding Company Act of 1956 (BHCA) allowed States to prohibit an out-of-state bank holding company from owning an in-state \"bank,\" which was defined to include an institution that both accepted demand deposits and engaged in the commercial lending business. In 1981, appellee, an Illinois bank holding company, applied to Florida to establish and operate an \"industrial savings bank\" (ISB) in that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"LULAC v. Perry","cite":"133 S. Ct. 96","y":2012,"url":"https://www.courtlistener.com/c/S.%20Ct./133/96/","sc":1,"by":{"1":"9"}},{"t":"case","label":"LULAC v. Perry","cite":"548 U.S. 399","y":2006,"id":"2005/05-204","sc":1,"sum":"The Supreme Court held that the Texas Legislature's redistricting plan did not violate the Constitution, but that part of the plan violated the Voting Rights Act. Justice Anthony Kennedy, writing for a majority of the justices, stated that District 23 had been redrawn in such a way as to deny Latino voters as a group the opportunity to elect a candidate of their choosing, thereby violating the Voting Rights Act.","sumSrc":"Oyez","by":{"1":"passim","2":"5, 29, 30, 37","3":"passim","4":"44, 47","5":"22, 26, 27"}},{"t":"case","label":"McClesky v. Kemp","cite":"481 U.S. 279","y":1987,"id":"1986/84-6811","sc":1,"sum":"The Court decided it was not a violation of the Eighth Amendment when purposeful discrimination could not be proven.","sumSrc":"Oyez","by":{"1":"26","2":"28"}},{"t":"case","label":"Miller v. Johnson","cite":"515 U.S. 900","y":1995,"id":"1994/94-631","sc":1,"sum":"In some instances, a reapportionment plan may be so highly irregular and bizarre in shape that it rationally cannot be understood as anything other than an effort to segregate voters based on race. Applying the rule laid down in Shaw v. Reno requires strict scrutiny whenever race is the \"overriding, predominant force\" in the redistricting process.","sumSrc":"Oyez","by":{"1":"passim","2":"passim","3":"36","4":"52","5":"2, 8, 9, 11"}},{"t":"case","label":"Ne. Fla. Chapter of Associated Gen. Contractors of Am. v. City of Jacksonville","cite":"508 U.S. 656","y":1993,"id":"1992/91-1721","sc":1,"sum":"The majority determined that the association members' possible lack of fair opportunity as a consequence of the ordinance would have constituted injury. Since the association members would have competed for the reserved city contracts in the absence of the ordinance, the Court found that they did have standing and reversed the judgment of the Court of Appeals.","sumSrc":"Oyez","by":{"1":"43","3":"31","4":"40"}},{"t":"case","label":"Palmer v. Thompson","cite":"403 U.S. 217","y":1971,"id":"1970/107","sc":1,"sum":"Following the Court of Appeals' affirmance of a District Court judgment invalidating enforced segregation on equal protection grounds, the city council of Jackson, Mississippi, desegregated its public recreational facilities, including its five public parks, except for their swimming pools. Stating that the pools could not be operated safely and economically on an integrated basis, the council closed four city-owned …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 49","2":"33"}},{"t":"case","label":"Perry v. Perez","cite":"565 U.S. 388","y":2012,"id":"2011/11-713","sc":1,"sum":"A case which the Court remanded regarding whether or not a Texas district court abused its discretion under the Voting Rights Act when it redrew 36 districts.","sumSrc":"Oyez","by":{"1":"passim","2":"passim","3":"5, 17, 18, 41","4":"passim","5":"1, 3, 13, 22"}},{"t":"case","label":"Pers. Adm’r of Mass. v. Feeney","cite":"442 U.S. 256","y":1979,"id":"1978/78-233","sc":1,"sum":"The Court held that the law was enacted to serve \"legitimate and worthy purposes\" and not to discriminate on the basis of sex. Even though few women benefitted from the scheme, Justice Stewart argued that \"veteran status is not uniquely male.\" Furthermore, the law placed many men who were not veterans at a disadvantage as well.","sumSrc":"Oyez","by":{"1":"passim","2":"25","3":"47","5":"8, 11, 25"}},{"t":"case","label":"Salazar ex rel. Salazar v. Dist. of Columbia","cite":"671 F.3d 1258","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/671/1258/","by":{"1":"19, 22"}},{"t":"case","label":"Sekhar v. United States","cite":"133 S. Ct. 2720","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Shaw v. Hunt","cite":"517 U.S. 899","y":1996,"id":"1995/94-923","sc":1,"sum":"In a 5-to-4 opinion by Chief Justice Rehnquist, the Court first confronted the threshold question of \"standing.\" It held that some of the appellants lacked proper standing to challenge the redistricting plan. Only those voters who resided in a congressional district alleged to have been created by racial gerrymandering had proper standing to challenge the constitutionality of that district's creation.","sumSrc":"Oyez","by":{"1":"49, 69","2":"6","3":"39, 42, 52","4":"52","5":"30"}},{"t":"case","label":"Shaw v. Reno","cite":"509 U.S. 630","y":1993,"id":"1992/92-357","sc":1,"sum":"The Court held that the redistricting of North Carolina was evidence of an attempt to separate voters based on race, and thus raised a constitutional issue under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"passim","2":"5, 26","3":"28, 35, 36","4":"25, 52, 53, 54","5":"20, 22, 25"}},{"t":"case","label":"Shelby County v. Holder","cite":"133 S. Ct. 2612","y":2013,"id":"2012/12-96","sc":1,"sum":"The Court found that Section 4 of the Voting Rights Act was unconstitutional.","sumSrc":"Oyez","by":{"1":"10","2":"3, 12, 27","4":"26","5":"4"}},{"t":"case","label":"Texas v. United States","cite":"133 S. Ct. 2885","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./133/2885/","sc":1,"by":{"1":"10"}},{"t":"case","label":"Texas v. United States","cite":"887 F. Supp. 2d 133","y":2012,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/887/133/","sum":"Explaining that CD34 offset changes to CD27 for purposes of VRA §5 retrogression.","sumSrc":"brief:1","by":{"1":"9, 50","2":"11","3":"19, 34","4":"14-15, 16-17, 18-19","5":"24"}},{"t":"case","label":"Thomas ex rel. D.M.T. v. Sch. Bd. St. Martin Par.","cite":"756 F.3d 380","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/380/","by":{"1":"19"}},{"t":"case","label":"U.S. Dep’t of Labor v. Triplett","cite":"494 U.S. 715","y":1990,"id":"1989/88-1671","sc":1,"sum":"The Black Lung Benefits Act of 1972 prohibits attorneys from receiving fees for representing claimants except as approved by petitioner Department of Labor. In implementing this provision, the Department promulgated approval procedures which, inter alia, invalidate all contractual fee arrangements. Respondent Triplett (hereinafter respondent), an attorney, violated the Department's fee scheme when he agreed to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Vt. Agency of Nat. Res. v. U.S. ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Wise v. Lipscomb","cite":"437 U.S. 535","y":1978,"id":"1977/77-529","sc":1,"ar":1,"sum":"The judgment is reversed and the case is remanded. Pp. 539-547; 547-549. 551 F. 2d 1043, reversed and remanded. MR. JUSTICE WHITE, joined by MR. JUSTICE STEWART, concluded:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31","2":"22, 29, 42"}},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","stext":{"head":"§1253. Direct appeals from decisions of three-judge courts","paras":[[0,"Except as otherwise provided by law, any party may appeal to the Supreme Court from an order granting or denying, after notice and hearing, an interlocutory or permanent injunction in any civil action, suit or proceeding required by any Act of Congress to be heard and determined by a district court of three judges."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1253?type=usc&year=mostrecent&link-type=html"},"head":"§1253. Direct appeals from decisions of three-judge courts","tname":"Judiciary and Judicial Procedure","by":{"1":"3, 19, 23","2":"2, 16, 20, 23","3":"26","4":"passim","5":"5"}},{"t":"usc","label":"52 U.S.C. § 10301","url":"https://www.law.cornell.edu/uscode/text/52/10301","subs":["(a)","(b)"],"stext":{"head":"§10301. Denial or abridgement of right to vote on account of race or color through voting qualifications or prerequisites; establishment of violation","paras":[[0,"(a) No voting qualification or prerequisite to voting or standard, practice, or procedure shall be imposed or applied by any State or political subdivision in a manner which results in a denial or abridgement of the right of any citizen of the United States to vote on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, as provided in subsection (b)."],[0,"(b) A violation of subsection (a) is established if, based on the totality of circumstances, it is shown that the political processes leading to nomination or election in the State or political subdivision are not equally open to participation by members of a class of citizens protected by subsection (a) in that its members have less opportunity than other members of the electorate to participate in the political process and to elect representatives of their choice. The extent to which members of a protected class have been elected to office in the State or political subdivision is one circumstance which may be considered: Provided, That nothing in this section establishes a right to have members of a protected class elected in numbers equal to their proportion in the population."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10301?type=usc&year=mostrecent&link-type=html"},"head":"§10301. Denial or abridgement of right to vote on account of race or color through voting qualifications or prerequisites; establishment of violation","tname":"Voting and Elections","by":{"1":"3","2":"3, 3, 4, 4","3":"passim","4":"passim, passim"}},{"t":"case","label":"Alabama Legislative Black Caucus v. Alabama","cite":"135 S. Ct. 1257","y":2015,"id":"2014/13-895","sc":1,"sum":"The Court held that states may not substitute their own extraneous goals for the traditional goals of the Voting Rights Act of 1965 when redrawing electoral districts.","sumSrc":"Oyez","by":{"2":"6, 44, 45"}},{"t":"case","label":"Burns v. Richardson","cite":"384 U.S. 73","y":1966,"id":"1965/318","sc":1,"sum":"The Hawaii Constitution provides that three small counties elect 15 of 25 state senators, while the fourth county (Oahu), with 79% of the State's population, elects 10. Under an apportionment authorized by the Constitution, Oahu has been allocated 36 of the 51 seats in the state house of representatives, the representatives being elected from multi-member districts apportioned on the basis of the number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Chen v. City of Houston","cite":"206 F.3d 502","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/206/502/","by":{"2":"34, 35"}},{"t":"case","label":"City of Cleburne v. Cleburne Living Ctr.","cite":"473 U.S. 432","y":1985,"id":"1984/84-468","sc":1,"sum":"In a unanimous judgment, the Court held that the denial of the special use permit to Cleburne Living Centers, Inc. was premised on an irrational prejudice against the mentally retarded, and hence unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"City of Mobile v. Bolden","cite":"446 U.S. 55","y":1980,"id":"1978/77-1844","sc":1,"sum":"The Court held that the Fifteenth Amendment did not entail \"the right to have Negro candidates elected,\" and that only purposefully discriminatory denials of the freedom to vote on the basis of race demanded constitutional remedies.","sumSrc":"Oyez","by":{"2":"28, 32","5":"20"}},{"t":"case","label":"Coleman v. Court of Appeals","cite":"566 U.S. 30","y":2012,"id":"2011/10-1016","sc":1,"sum":"The Court held that states have sovereign immunity to suits brought under the self-care provision of the Family and Medical Leave Act.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Garza v. County of Los Angeles","cite":"918 F.2d 763","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/918/763/","by":{"2":"4","4":"49","5":"22"}},{"t":"case","label":"Gulfstream Aerospace Corp. v. Mayacamas Corp.","cite":"485 U.S. 271","y":1988,"id":"1987/86-1329","sc":1,"sum":"Petitioner sued respondent in state court for breach of contract. Respondent did not remove the action to federal court, but, one month later, filed a diversity action against petitioner in the Federal District Court for breach of the same contract. The District Court denied petitioner's motion to stay or dismiss the action before it, finding that the facts of the case fell short of those necessary to justify the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Hayden v. Paterson","cite":"594 F.3d 150","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/594/150/","by":{"2":"30, 34"}},{"t":"case","label":"Johnson v. Governor","cite":"405 F.3d 1214","y":2005,"url":"https://www.courtlistener.com/c/F.3d/405/1214/","by":{"2":"34"}},{"t":"case","label":"Jones v. City of Lubbock","cite":"727 F.2d 364","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/727/364/","by":{"2":"35"}},{"t":"case","label":"Kirksey v. Board of Supervisors","cite":"554 F.2d 139","y":1977,"url":"https://www.courtlistener.com/c/F.2d/554/139/","by":{"2":"35"}},{"t":"case","label":"Lawyer v. Department of Justice","cite":"521 U.S. 567","y":1997,"id":"1996/95-2024","sc":1,"sum":"The Court held that the State exercised the choice to which it was entitled under our cases, that Lawyer had no right to block the settlement, and that he failed to point out any unconstitutionality in the proposed plan.","sumSrc":"Oyez","by":{"2":"22, 29"}},{"t":"case","label":"Mississippi State Chapter, Operation PUSH, Inc. v. Mabus","cite":"932 F.2d 400","y":1991,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/932/400/","sum":"Holding that plaintiff had failed to “establish[] that the Mississippi Legislature” had “a racially discriminatory purpose” in enacting its legislative remedy for a Section 2 violation.","sumSrc":"brief:2","by":{"2":"29"}},{"t":"case","label":"Mt. Healthy City Sch. Dist. Bd. of Educ. v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"sum":"Writing for a unanimous Court, Justice Rehnquist held that the school district was not entitled to sovereign immunity, which generally extended to the states themselves and to state officials in their official capacities. He reasoned that the board was more akin to a municipal corporation, given its independent power to issue bonds and levy taxes.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Purcell v. Gonzalez","cite":"549 U.S. 1","y":2006,"id":"2006/06-532","sc":1,"sum":"The Court decided that the U.S. Court of Appeals for the Ninth Circuit improperly granted an emergency injunction against the enforcement of Proposition 200.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Reno v. Bossier Parish Sch. Bd.","cite":"520 U.S. 471","y":1997,"id":"1996/95-1455","sc":1,"sum":"The Court ruled that preclearance under ?5 of the Voting Rights Act of 1965 may not be denied solely on the basis that a covered jurisdiction's new voting \"standard, practice, or procedure\" violates ? 2 of the Act.","sumSrc":"Oyez","by":{"2":"25, 26, 28, 36","3":"31"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Rogers v. Lodge","cite":"458 U.S. 613","y":1982,"id":"1981/80-2100","sc":1,"sum":"In a 6-to-3 decision, the Court held that the at-large system of elections in Burke County violated the Equal Protection Clause of the Fourteenth Amendment. The Court held that there was sufficient evidence to warrant the conclusion that the at-large system was operated as a purposeful device to further racial discrimination.","sumSrc":"Oyez","by":{"2":"4, 25, 26","4":"41, 42, 44-45, 48","5":"21"}},{"t":"case","label":"Schaffer v. Weast","cite":"546 U.S. 49","y":2005,"id":"2005/04-698","sc":1,"sum":"In a 6 to 2 ruling, the Supreme Court held that the party bringing the suit bears the burden of proof, whether that party is the parents or the school system. In the majority opinion, Justice Sandra Day O'Connor wrote that \"absent some reason to believe that Congress intended otherwise, ... we will conclude that the burden of persuasion lies where it usually falls, upon the party seeking relief.\".","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Thornburgh v. Gingles","cite":"478 U.S. 30","y":1986,"id":"1985/83-1968","sc":1,"sum":"The Court found that five of the six contested districts discriminated against blacks by diluting the power of their collective vote. Justice William J. Brennan Jr. delivered the opinion for a unanimous court.","sumSrc":"Oyez","by":{"2":"4, 47, 48","3":"passim","4":"passim","5":"21"}},{"t":"case","label":"Village of Arlington Heights v. Metropolitan Hous. Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"ar":5,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"2":"25, 26, 27, 28, 29","3":"30","4":"36, 43, 44"}},{"t":"case","label":"Voinovich v. Quilter","cite":"507 U.S. 146","y":1993,"id":"1992/91-1618","sc":1,"sum":"Pursuant to the Ohio Constitution's requirement that electoral districts for the state legislature be reapportioned every 10 years, appellant James Tilling drafted and the state apportionment board adopted in 1991 an apportionment plan that created several districts in which a majority of the population is a member of a specific minority group. Appellees, Democratic board members who voted against the plan and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4, 26"}},{"t":"case","label":"Washington v. Davis","cite":"426 U.S. 229","y":1976,"id":"1975/74-1492","sc":1,"sum":"In a 7-to-2 decision, the Court held that the procedures and written personnel test did not constitute racial discrimination under the Equal Protection Clause. The Court found that the Clause was designed to prevent official discrimination on the basis of race; laws or other official acts that had racially disproportionate impacts did not automatically become constitutional violations.","sumSrc":"Oyez","by":{"2":"25, 27"}},{"t":"case","label":"Weinberger v. Wiesenfeld","cite":"420 U.S. 636","y":1975,"id":"1974/73-1892","sc":1,"sum":"The Court held that the gender-based distinction in Social Security benefits violates the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Whitcomb v. Chavis","cite":"403 U.S. 124","y":1971,"id":"1970/92","sc":1,"sum":"The judgment is reversed and the case remanded. Pp. 140-170; 179-180. 305 F. Supp. 1364, reversed and remanded. WHITCOMB v. CHAVIS","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23","4":"31, 32","5":"7"}},{"t":"case","label":"Whitcomb v. Davis","cite":"403 U.S. 914","y":1971,"url":"https://supreme.justia.com/cases/federal/us/403/914/","sc":1,"by":{"2":"23"}},{"t":"const","label":"Amendment XIV","clauses":[["equal-protection","Equal Protection Clause"]],"by":{"2":"3, 4, 5, 44, 46","3":"passim","4":"passim"}},{"t":"usc","label":"52 U.S.C. § 10302","url":"https://www.law.cornell.edu/uscode/text/52/10302","subs":["(c)"],"stext":{"head":"§10302. Proceeding to enforce the right to vote","paras":[[0,"(a) Authorization by court for appointment of Federal observers"],[0,"Whenever the Attorney General or an aggrieved person institutes a proceeding under any statute to enforce the voting guarantees of the fourteenth or fifteenth amendment in any State or political subdivision the court shall authorize the appointment of Federal observers by the Director of the Office of Personnel Management in accordance with section 1973d 1 of title 42 to serve for such period of time and for such political subdivisions as the court shall determine is appropriate to enforce the voting guarantees of the fourteenth or fifteenth amendment (1) as part of any interlocutory order if the court determines that the appointment of such observers is necessary to enforce such voting guarantees or (2) as part of any final judgment if the court finds that violations of the fourteenth or fifteenth amendment justifying equitable relief have occurred in such State or subdivision: Provided, That the court need not authorize the appointment of observers if any incidents of denial or abridgement of the right to vote on account of race or color, or in contravention of the voting guarantees set forth in section 10303(f)(2) of this title (1) have been few in number and have been promptly and effectively corrected by State or local action, (2) the continuing effect of such incidents has been eliminated, and (3) there is no reasonable probability of their recurrence in the future."],[0,"(b) Suspension of use of tests and devices which deny or abridge the right to vote"],[0,"If in a proceeding instituted by the Attorney General or an aggrieved person under any statute to enforce the voting guarantees of the fourteenth or fifteenth amendment in any State or political subdivision the court finds that a test or device has been used for the purpose or with the effect of denying or abridging the right of any citizen of the United States to vote on account of race or color, or in contravention of the voting guarantees set forth in section 10303(f)(2) of this title, it shall suspend the use of tests and devices in such State or political subdivisions as the court shall determine is appropriate and for such period as it deems necessary."],[0,"(c) Retention of jurisdiction to prevent commencement of new devices to deny or abridge the right to vote"],[0,"If in any proceeding instituted by the Attorney General or an aggrieved person under any statute to enforce the voting guarantees of the fourteenth or fifteenth amendment in any State or political subdivision the court finds that violations of the fourteenth or fifteenth amendment justifying equitable relief have occurred within the territory of such State or political subdivision, the court, in addition to such relief as it may grant, shall retain jurisdiction for such period as it may deem appropriate and during such period no voting qualification or prerequisite to voting or standard, practice, or procedure with respect to voting different from that in force or effect at the time the proceeding was commenced shall be enforced unless and until the court finds that such qualification, prerequisite, standard, practice, or procedure does not have the purpose and will not have the effect of denying or abridging the right to vote on account of race or color, or in contravention of the voting guarantees set forth in section 10303(f)(2) of this title: Provided, That such qualification, prerequisite, standard, practice, or procedure may be enforced if the qualification, prerequisite, standard, practice, or procedure has been submitted by the chief legal officer or other appropriate official of such State or subdivision to the Attorney General and the Attorney General has not interposed an objection within sixty days after such submission, except that neither the court's finding nor the Attorney General's failure to object shall bar a subsequent action to enjoin enforcement of such qualification, prerequisite, standard, practice, or procedure."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10302?type=usc&year=mostrecent&link-type=html"},"head":"§10302. Proceeding to enforce the right to vote","tname":"Voting and Elections","by":{"2":"12","4":"25, 26, 35"}},{"t":"usc","label":"52 U.S.C. § 10304","url":"https://www.law.cornell.edu/uscode/text/52/10304","subs":["(a)"],"stext":{"head":"§10304. Alteration of voting qualifications; procedure and appeal; purpose or effect of diminishing the ability of citizens to elect their preferred candidates","paras":[[0,"(a) Whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the first sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1964, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the second sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1968, or whenever a State or political subdivision with respect to which the prohibitions set forth in section 10303(a) of this title based upon determinations made under the third sentence of section 10303(b) of this title are in effect shall enact or seek to administer any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting different from that in force or effect on November 1, 1972, such State or subdivision may institute an action in the United States District Court for the District of Columbia for a declaratory judgment that such qualification, prerequisite, standard, practice, or procedure neither has the purpose nor will have the effect of denying or abridging the right to vote on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, and unless and until the court enters such judgment no person shall be denied the right to vote for failure to comply with such qualification, prerequisite, standard, practice, or procedure: Provided, That such qualification, prerequisite, standard, practice, or procedure may be enforced without such proceeding if the qualification, prerequisite, standard, practice, or procedure has been submitted by the chief legal officer or other appropriate official of such State or subdivision to the Attorney General and the Attorney General has not interposed an objection within sixty days after such submission, or upon good cause shown, to facilitate an expedited approval within sixty days after such submission, the Attorney General has affirmatively indicated that such objection will not be made. Neither an affirmative indication by the Attorney General that no objection will be made, nor the Attorney General's failure to object, nor a declaratory judgment entered under this section shall bar a subsequent action to enjoin enforcement of such qualification, prerequisite, standard, practice, or procedure. In the event the Attorney General affirmatively indicates that no objection will be made within the sixty-day period following receipt of a submission, the Attorney General may reserve the right to reexamine the submission if additional information comes to his attention during the remainder of the sixty-day period which would otherwise require objection in accordance with this section. Any action under this section shall be heard and determined by a court of three judges in accordance with the provisions of section 2284 of title 28 and any appeal shall lie to the Supreme Court."],[0,"(b) Any voting qualification or prerequisite to voting, or standard, practice, or procedure with respect to voting that has the purpose of or will have the effect of diminishing the ability of any citizens of the United States on account of race or color, or in contravention of the guarantees set forth in section 10303(f)(2) of this title, to elect their preferred candidates of choice denies or abridges the right to vote within the meaning of subsection (a) of this section."],[0,"(c) The term \"purpose\" in subsections (a) and (b) of this section shall include any discriminatory purpose."],[0,"(d) The purpose of subsection (b) of this section is to protect the ability of such citizens to elect their preferred candidates of choice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/52/10304?type=usc&year=mostrecent&link-type=html"},"head":"§10304. Alteration of voting qualifications; procedure and appeal; purpose or effect of diminishing the ability of citizens to elect their preferred candidates","tname":"Voting and Elections","by":{"2":"7","3":"13, 16, 19, 31","4":"14"}},{"t":"usc","label":"52 U.S.C. § 10308","url":"https://www.law.cornell.edu/uscode/text/52/10308","subs":["(d)"],"by":{"2":"3"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(a)(1)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"2":"17, 20","3":"26, 27","4":"30, 33","5":"5, 5"}},{"t":"usc","label":"28 U.S.C. § 2284","url":"https://www.law.cornell.edu/uscode/text/28/2284","subs":["(a)"],"by":{"2":"17, 20, 23"}},{"t":"case","label":"Anderson v. Bessemer City","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"sum":"The Court of Appeals misapprehended and misapplied the clearlyerroneous standard and accordingly erred in denying petitioner relief under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"48, 49","4":"41-42"}},{"t":"case","label":"Bear Lake & River Waterworks & Irrigation Co. v. Garland","cite":"164 U.S. 1","y":1896,"id":"scdb/1896-001","sc":1,"sum":"On the 16th of August, 1889, a statute was In force in the Territory of Utah providing for the creation of mechanic’s Hens for work done or materials furnished under contracts in making improvements upon land; but, in order to enforce his Hen a contractor was required, within 60 days after completion of the contract, to file for record a claim stating his demand, and describing the property to be subjected to it; …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"29","4":"40"}},{"t":"case","label":"Covington v. North Carolina","cite":"316 F.R.D. 117","y":2016,"court":"M.D.N.C.","url":"https://www.courtlistener.com/c/F.R.D./316/117/","by":{"3":"35-36"}},{"t":"case","label":"League of United Latin American Citizens v. Perry","cite":"457 F. Supp. 2d 716","y":2006,"court":"E.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/457/716/","by":{"3":"3, 4"}},{"t":"case","label":"Oneida County v. Oneida Indian Nation of New York State","cite":"470 U.S. 226","y":1985,"id":"1984/83-1065","sc":1,"sum":"Respondent Indian Tribes (hereafter respondents) brought an action in Federal District Court against petitioner counties (hereafter petitioners), alleging that respondents' ancestors conveyed tribal land to New York State, under a 1795 agreement that violated the Nonintercourse Act of 1793-which provided that no person or entity could purchase Indian land without the Federal Government's approval-and that thus the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"29","4":"40"}},{"t":"case","label":"Pierce v. Underwood","cite":"487 U.S. 552","y":1988,"id":"1987/86-1512","sc":1,"sum":"One of petitioner's predecessors as Secretary of Housing and Urban Development decided not to implement an \"operating subsidy\" program authorized by federal statute, which was intended to provide payments to owners of Government-subsidized apartment buildings to offset rising utility expenses and property taxes. Various plaintiffs, including respondent members of a nationwide class of Government-subsidized housing …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"31"}},{"t":"case","label":"Posadas v. Nat’l City Bank of N.Y.","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"3":"29"}},{"t":"case","label":"Trump v. Int’l Refugee Assistance Project","cite":"137 S. Ct. 2080","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/2080/","sc":1,"by":{"3":"32"}},{"t":"case","label":"Univ. of Texas v. Camenisch","cite":"451 U.S. 390","y":1981,"id":"1980/80-317","sc":1,"sum":"The question whether a preliminary injunction should have been issued is moot because the terms of the injunction have been fully and irrevocably carried out, but, as the Court of Appeals correctly noted, the question whether the University must pay for the interpreter remains for trial on the merits.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"33","4":"37, 38","5":"14"}},{"t":"case","label":"Walters v. Nat’l Ass’n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"sum":"Title 38 U. S. C. § 3404(c) limits to $10 the fee that may be paid an attorney or agent who represents a veteran seeking benefits from the Veterans' Administration (VA) for service-connected death or disability. Appellees (two veterans' organizations, three individual veterans, and a veteran's widow) brought an action in Federal District Court claiming that the fee limitation denied them any realistic opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"33"}},{"t":"usc","label":"52 U.S.C. § 10101","url":"https://www.law.cornell.edu/uscode/text/52/10101","by":{"3":"passim"}},{"t":"rule","label":"Fed. R. Civ. P. 52","url":"https://www.law.cornell.edu/rules/frcp/rule_52","subs":["(a)"],"by":{"3":"24","4":"28, 41, 42"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","subs":["(d)"],"by":{"3":"27"}},{"t":"case","label":"Chavis v. Whitcomb","cite":"307 F. Supp. 1362","y":1969,"court":"S.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp./307/1362/","by":{"4":"32"}},{"t":"case","label":"City of Pleasant Grove v. United States","cite":"479 U.S. 462","y":1987,"id":"1986/85-1244","sc":1,"sum":"Appellant, an Alabama city that has a long history of racial discrimination and that until recently had an all-white population, is covered by §5 of the Voting Rights Act of 1965 (Act) and accordingly must seek preclearance before instituting any change in a standard, practice, or procedure affecting voting. Appellant sought approval by the Attorney General for the annexation of two parcels of land, one vacant …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"48","5":"21"}},{"t":"case","label":"City of Richmond v. J.A. Croson Co.","cite":"488 U.S. 469","y":1989,"id":"1988/87-998","sc":1,"sum":"In a 6-to-3 decision, the Court held that \"generalized assertions\" of past racial discrimination could not justify \"rigid\" racial quotas for the awarding of public contracts. Justice O'Connor's opinion noted that the 30 percent quota could not be tied to \"any injury suffered by anyone,\" and was an impermissible employment of a suspect classification.","sumSrc":"Oyez","by":{"4":"53"}},{"t":"case","label":"City of Richmond v. United States","cite":"422 U.S. 358","y":1975,"id":"1974/74-201","sc":1,"sum":"In 1969 a Virginia court approved annexation by the city of Richmond, effective January 1, 1970, of an adjacent area in Chesterfield County, which reduced the proportion of Negroes in Richmond from 52% to 42%. The preannexation nine-man city council, which was elected at large, had three members who were endorsed by a Negro civic organization. In a postannexation at-large election in 1970, three of the nine members …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"48","5":"21"}},{"t":"case","label":"Community Nutrition Inst. v. Block","cite":"749 F.2d 50","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/749/50/","sum":"Noting that a court’s “tentative assessment made to support the issuance of a preliminary injunction” is “not a final determination” and “is not even law of the case”.","sumSrc":"brief:4","by":{"4":"37"}},{"t":"case","label":"Georgia v. Ashcroft","cite":"539 U.S. 461","y":2003,"id":"2002/02-182","sc":1,"sum":"The Court held that the District Court failed to consider all the relevant factors when it examined whether Georgia's Senate plan resulted in a retrogression of black voters' effective exercise of the electoral franchise.","sumSrc":"Oyez","by":{"4":"8","5":"21, 23"}},{"t":"case","label":"Goldstein v. Cox","cite":"396 U.S. 471","y":1970,"id":"1969/66","sc":1,"sum":"The only interlocutory orders that this Court has power to review under § 1253 are those granting or denying preliminary injunctions, and therefore this Court lacks jurisdiction to review the District Court's interlocutory order, which involved no question of preliminary injunctive relief. Pp. 475-479. 299 F. Supp. 1389, appeal dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"29, 30, 34"}},{"t":"case","label":"Hazelwood Sch. Dist. v. United States","cite":"433 U.S. 299","y":1977,"id":"1976/76-255","sc":1,"sum":"The Supreme Court held that the court of appeals used the correct statistical comparison, but erred in determining the relevant labor market. The court of appeals also failed to consider that Hazelwood may have been able to rebut some of the statistics with evidence of its hiring practices post Title VII. The Court remanded the case for further consideration of the relevant labor market.","sumSrc":"Oyez","by":{"4":"47"}},{"t":"case","label":"Keyes v. Denver Sch. Dist. No. 1","cite":"413 U.S. 189","y":1973,"id":"1972/71-507","sc":1,"sum":"The Court modified and remanded the lower court decision and held that when part of a school system is found to be segregated, a \"prima facie case of unlawful [systematic] segregative design\" becomes apparent. The school district involved assumes the burden of proving that it operated without \"segregative intent\" on a system-wide basis.","sumSrc":"Oyez","by":{"4":"39, 47"}},{"t":"case","label":"Mitchell v. Donovan","cite":"398 U.S. 427","y":1970,"id":"1969/726","sc":1,"sum":"An order granting or denying only a declaratory judgment may not be appealed to this Court under § 1253. Rockefeller v. Catholic Medical Center, 397 U. S, 820. 300 F. Supp. 1145, vacated and remanded. Lynn S. Castnerargued the cause for appellants. With him on the brief were Melvin L. Wulf and EleanorHolmes Norton.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"29","5":"7"}},{"t":"case","label":"N.C. State Conference of the NAACP v. McCrory","cite":"831 F.3d 204","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/204/","by":{"4":"43"}},{"t":"case","label":"Sole v. Wyner","cite":"551 U.S. 74","y":2007,"id":"2006/06-531","sc":1,"sum":"Justice Ruth Bader Ginsburg's opinion for the unanimous Court held that a preliminary injunction that is later reversed or otherwise undone cannot be the basis for \"prevailing party\" status for purposes of awarding attorney's fees.","sumSrc":"Oyez","by":{"4":"38","5":"14"}},{"t":"case","label":"United States v. Fordice","cite":"505 U.S. 717","y":1992,"id":"1991/90-1205","sc":1,"sum":"A state's duty is not discharged \"until it eradicates policies and practices traceable to its prior de jure dual system that continues to foster segregation.\" Race-neutral admissions are not a sufficient corrective to constitutional violations of a dual system. Different admissions criteria, and different missions for university system components, may have racially discriminatory effects perpetuating the old system.","sumSrc":"Oyez","by":{"4":"46-47","5":"10"}},{"t":"case","label":"United States v. Virginia","cite":"518 U.S. 515","y":1996,"id":"1995/94-1941","sc":1,"sum":"The Court found that the Virginia Military Institute's policy of only admitting and serving males was unconstitutional.","sumSrc":"Oyez","by":{"4":"53"}},{"t":"case","label":"White v. Regester","cite":"412 U.S. 755","y":1973,"id":"1972/72-147","sc":1,"sum":"In this litigation challenging the Texas 1970 legislative reapportionment scheme, a three-judge District Court held that the House plan, statewide, contained constitutionally impermissi]ile deviations from population equality, and that the multimember districts provided for Bexar and Dallas Counties invidiously discriminated against cognizable racial or ethnic groups. Though the entire plan was declared invalid, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"29, 42"}},{"t":"case","label":"Whitford v. Gill","cite":"2017 WL 2623104","y":2017,"court":"W.D. Wis. Feb. 22","by":{"4":"31"}},{"t":"usc","label":"52 U.S.C. § 10303","url":"https://www.law.cornell.edu/uscode/text/52/10303","subs":["(b)"],"by":{"4":"26"}}]};